function c(e){return e?Array.from(e.childNodes).filter(t=>t.nodeType===Node.TEXT_NODE).map(t=>t.textContent?.trim()??"").find(Boolean)??e?.textContent?.trim()??"":""}function y(e){if(!e)return{id:"",name:"",date:""};const n=e.closest("tr");if(!n)return{id:"",name:"",date:""};const t=Array.from(n.querySelectorAll("td")),s=!!n.querySelector('input[name="daily_salary_ids"]')?2:1,i=s+1,d=c(t[s]??null),a=c(t[i]??null),o=t.find(u=>/\d{4}-\d{2}-\d{2}/.test(u.textContent??""))??null,r=c(o);return{id:d,name:a,date:r}}function m(){const e=Array.from(document.querySelectorAll('input[name="daily_salary_ids"]:checked')),n=document.getElementById("selected-daily-salary");if(!n)return;let t=e.length===0?"No daily salaries selected":"";e.length>0&&(t=e.map(i=>{const{id:d,name:a,date:o}=y(i),r=d&&a?`${d}/${a}`:d||a||"";return r&&o?`${r} - ${o}`:r||o}).filter(Boolean).join(", ")),n.textContent=t;const l=document.getElementById("selected-summary");l&&(l.style.display=e.length>0?"":"none")}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll('input[name="daily_salary_ids"]').forEach(e=>{e.addEventListener("change",()=>m())}),m()});
